''' This file is used to generate std1 folders given a set of geometries in an excel. So far, std1 were generated by an automated process. In this file,
an excel is the source, which has a param list of geometries and current for which std2 jobs are pending. These geometries are read one by one and then the standard std1 scan
currents are generated. '''

import numpy as np
import pandas as pd

# input file
std2File = 'dpits_align.xlsx'

#output file
std1Excel = 'std1_dpit_5mics_pending.xlsx'

# Dataframe
df2 = pd.read_excel(std2File,sheet_name='5mics')

# std1 currents
iApply = [7.5e-5, 1e-4, 2.5e-4]
stepZone = [0.25, 0.25, 0.25]
iZip = list(zip(iApply,stepZone))
numJobsPerGeom = len(iZip)

cols1 = ['rpit_1','rpit_2','theta_1','theta_2','I_apply','stepzone']
df3 = pd.DataFrame(columns = cols1)

while (not df2.empty):
	zSub = df2.loc[(df2['rpit_1'] == df2.iloc[0,0]) & (df2['rpit_2'] == df2.iloc[0,1]) & (df2['theta_1'] == df2.iloc[0,2]) & (df2['theta_2'] == df2.iloc[0,3])] # Select geometry
	zSubIndex = zSub.index
	r1 = [df2.iloc[0,0]] * numJobsPerGeom
	print(r1)
	r2 = [df2.iloc[0,1]]*numJobsPerGeom
	t1 = [df2.iloc[0,2]]*numJobsPerGeom
	t2 = [df2.iloc[0,3]]*numJobsPerGeom
	outList = list(zip(r1,r2,t1,t2,iApply,stepZone))
	dfTemp = pd.DataFrame(outList,columns=cols1)
	df3 = pd.concat([df3,dfTemp],ignore_index=True)

	df2 = df2.drop(zSubIndex)

print(df3)
df3.to_excel(std1Excel)